// ================= FUNGSI NORMALISASI INPUT =================
function normalizeSearchInput(input) {
    let normalized = input.toLowerCase().trim();
    normalized = normalized
        .replace(/abad ke[- ]?(\d+)/gi, 'abad $1')
        .replace(/ke-?(\d+)/gi, '$1')
        .replace(/tahun ke-?(\d+)/gi, '$1')
        .replace(/(\d+)an/gi, '$1')
        .replace(/(\d+)[\- ]?an/gi, '$1');
    return normalized;
}

// ================= FUNGSI PENCARIAN LIVE =================
function liveSearch() {
    let input = document.getElementById("searchInput").value;
    const results = document.getElementById("searchResults");
    if (!results) return;

    results.innerHTML = "";

    input = normalizeSearchInput(input);
    if (input === "" || input.length < 1) {
        results.style.display = "none";
        return;
    }

    // Support angka 1 digit juga
    const terms = input.split(/\s+/).filter(term => {
        if (/^\d+$/.test(term)) return term.length >= 1;  // angka boleh 1 digit
        return term.length >= 2;                          // kata minimal 2 huruf
    });

    if (terms.length === 0) {
        results.style.display = "none";
        return;
    }

    let foundResults = [];

    for (let key in contentDatabase) {
        const page = contentDatabase[key];
        
        const searchable = (
            page.title.toLowerCase() + " " +
            page.keywords.join(" ") + " " +
            (page.fullText || "").toLowerCase()
        );

        const allMatch = terms.every(term => searchable.includes(term));

        if (allMatch) {
            const isTitleMatch = page.title.toLowerCase().includes(input);
            foundResults.push({
                title: page.title,
                url: page.url,
                match: isTitleMatch ? 'title' : 'content'
            });
        }
    }

    const otherPages = [
        { title: "Beranda", url: "sidkel4.html" },
        { title: "Anggota Kelompok", url: "anggota.html" }
    ];

    otherPages.forEach(page => {
        const searchable = page.title.toLowerCase();
        if (terms.every(term => searchable.includes(term))) {
            foundResults.push({
                title: page.title,
                url: page.url,
                match: 'title'
            });
        }
    });

    if (foundResults.length > 0) {
        foundResults.forEach(result => {
            const div = document.createElement("div");
            div.innerHTML = `
                <strong>${result.title}</strong>
                ${result.match === 'content' ? '<br><small style="color: #666;">Ditemukan dalam konten</small>' : ''}
            `;
            div.style.cursor = "pointer";
            div.style.padding = "8px 12px";
            div.style.borderBottom = "1px solid #eee";
            div.onclick = () => navigateWithSearch(result.url, input);
            results.appendChild(div);
        });
        results.style.display = "block";
    } else {
        const div = document.createElement("div");
        div.innerHTML = '<em style="color: #999;">Tidak ada hasil ditemukan</em>';
        div.style.padding = "12px";
        results.appendChild(div);
        results.style.display = "block";
    }
}

// ================= NAVIGASI DENGAN PARAMETER PENCARIAN =================
function navigateWithSearch(url, keyword) {
    let finalUrl = url;
    const currentPath = window.location.pathname;

    if (currentPath.includes('/pages/')) {
        if (url.includes('pages/')) {
            finalUrl = url.replace('pages/', './');
        } else {
            finalUrl = '../' + url;
        }
    }

    finalUrl += (finalUrl.includes('?') ? '&' : '?') + 'search=' + encodeURIComponent(keyword);
    location.href = finalUrl;
}

// ================= AUTO HIGHLIGHT =================
function autoHighlight() {
    const urlParams = new URLSearchParams(window.location.search);
    const searchKeyword = urlParams.get('search');
    
    if (searchKeyword) {
        const searchInput = document.getElementById('searchInput');
        if (searchInput) searchInput.value = searchKeyword;
        
        setTimeout(() => {
            highlightText(searchKeyword);
            const firstMark = document.querySelector('mark');
            if (firstMark) firstMark.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }, 150);
    }
}

// ================= HIGHLIGHT TEXT =================
function highlightText(searchStr) {
    if (!searchStr || searchStr.trim().length < 1) return;
    
    removeHighlight();
    
    const terms = searchStr.toLowerCase().trim().split(/\s+/).filter(t => t.length >= 1);
    
    const elements = document.querySelectorAll(
        ".card p, .card h2, .card h3, .card h4, .card b, .card li, " +
        ".intro-card p, .intro-card h2, .content p, article p, section p"
    );
    
    elements.forEach(el => {
        terms.forEach(term => {
            if (term) highlightInElement(el, term);
        });
    });
}

function highlightInElement(element, word) {
    const regex = new RegExp(`(${escapeRegex(word)})`, 'gi');
    const walker = document.createTreeWalker(element, NodeFilter.SHOW_TEXT, null, false);
    const nodesToReplace = [];
    
    let node;
    while (node = walker.nextNode()) {
        if (regex.test(node.nodeValue)) nodesToReplace.push(node);
    }
    
    nodesToReplace.forEach(node => {
        const span = document.createElement('span');
        span.innerHTML = node.nodeValue.replace(regex, '<mark>$1</mark>');
        node.parentNode.replaceChild(span, node);
    });
}

function escapeRegex(str) {
    return str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function removeHighlight() {
    document.querySelectorAll("mark").forEach(mark => {
        const parent = mark.parentNode;
        parent.replaceChild(document.createTextNode(mark.textContent), mark);
        parent.normalize();
    });
}

// ================= CLEAR SEARCH =================
function clearSearch() {
    const searchInput = document.getElementById('searchInput');
    const searchResults = document.getElementById('searchResults');
    
    if (searchInput) searchInput.value = '';
    if (searchResults) searchResults.style.display = 'none';
    
    removeHighlight();
    
    const url = new URL(window.location);
    url.searchParams.delete('search');
    window.history.replaceState({}, '', url);
}

// ================= FLOATING BOTTOM NAV =================
const bottomNav = document.getElementById('bottomNav');
if (bottomNav) {
    window.addEventListener('scroll', () => {
        if (window.scrollY > 300) {
            bottomNav.classList.add('show');
        } else {
            bottomNav.classList.remove('show');
        }
    });
}

function scrollToTop() {
    window.scrollTo({ top: 0, behavior: 'smooth' });
}

function goHome() {
    const currentPath = window.location.pathname;
    location.href = currentPath.includes('/pages/') ? '../sidkel4.html' : 'sidkel4.html';
}

// ================= KEYBOARD SHORTCUTS =================
document.addEventListener('keydown', (e) => {
    if ((e.ctrlKey || e.metaKey) && e.key === 'k') {
        e.preventDefault();
        const searchInput = document.getElementById('searchInput');
        if (searchInput) {
            searchInput.focus();
            searchInput.select();
        }
    }
    if (e.key === 'Escape') clearSearch();
});

// ================= INITIALIZATION =================
document.addEventListener("DOMContentLoaded", () => {
    autoHighlight();

    const searchInput = document.getElementById('searchInput');
    if (searchInput) {
        searchInput.addEventListener('input', liveSearch);
    }

    document.addEventListener('click', (e) => {
        const searchBox = document.querySelector('.search-box');
        const searchResults = document.getElementById('searchResults');
        if (searchBox && !searchBox.contains(e.target) && searchResults) {
            searchResults.style.display = 'none';
        }
    });

    // Tampilkan card pertama jika ada
    const cards = document.querySelectorAll('.card');
    if (cards.length > 0) cards[0].style.display = 'block';

});
